import{l as n}from"./index-BuB3Xdwb.js";import{t as h}from"./terse-A2TJSHx3.js";const d={"Jupiter|Mars":{plain:"Jupiter and Mars are the planet of increase and the planet of the cut. One enlarges what it touches; the other narrows it to a point.",reading:"Traditional texts read the pairing as expansion meeting force: the general and the advocate, the campaign and its cost. Medieval sources placed it over the professions that push a claim outward and need an edge to do it. Where one loosens a boundary, the other draws one.",principle:"In the grading set out in Ptolemy's Tetrabiblos, Jupiter is the greater benefic and Mars the lesser malefic, so this is one of the pairings that scheme was built to describe: benefit and harm working on the same matter. Hellenistic practice also splits them by sect, Jupiter belonging to the day and Mars to the night, so the pair rarely acts with one voice. On the Golden Dawn Tree of Life they sit at Chesed and Geburah, mercy and severity facing each other across the pillars, joined by the path of Teth, which carries the card of Strength.",energies:["increase","campaign","advocacy","decisive force","appetite for scale"],tensions:["expansion against restraint","zeal against measure","the claim outrunning the means"],attributions:[{lineage:"Ptolemaic",claim:"Jupiter is beneficent and Mars maleficent; a mixture of the two is read as good tempered by harm."},{lineage:"Hellenistic",claim:"Jupiter is of the diurnal sect and Mars of the nocturnal, so the sect of a chart favours one and disadvantages the other."},{lineage:"Golden Dawn",claim:"Chesed and Geburah, the fourth and fifth sephiroth, joined by the path of Teth, Strength."}],correspondences:["metals: tin and iron","days: Thursday and Tuesday","sephiroth: Chesed and Geburah","Chaldean order: adjacent, Saturn-Jupiter-Mars"],contested:["The benefic and malefic labels are Hellenistic and were carried through the medieval tradition intact. Most modern psychological astrology has dropped them, reading Mars as drive rather than harm; traditional revivalists have restored them. The two readings do not reconcile.","Whether Jupiter moderates Mars or arms it is answered differently by the medieval and the modern sources."],prompts:["Which of the two is stronger by sign and house in this chart, and does that settle which one sets the terms?","Does the working here call for the expansion or for the cut?"]},"Jupiter|Mercury":{plain:"Jupiter and Mercury are the planet of the wide view and the planet of the exact word. One takes in the whole field; the other names one thing at a time.",reading:"The tradition gives Jupiter the law and Mercury the letter, Jupiter the doctrine and Mercury the commentary. Medieval texts read the pairing through the professions of learning: the jurist, the teacher, the scribe kept by a court. The two are held to agree on subject matter and to disagree on scale.",principle:"Ptolemy's Tetrabiblos sorts the planets into beneficent (Jupiter and Venus), maleficent (Saturn and Mars) and common (Mercury), which makes this a pairing where Mercury is read as taking Jupiter's tone rather than keeping its own. In the Chaldean order the two are separated by Mars, the Sun and Venus, placing them near opposite ends of the planetary ladder. On the Golden Dawn Tree they fall at Chesed on the Pillar of Mercy and Hod on the Pillar of Severity, with no path drawn directly between them; whatever passes between them in that system passes through Tiphareth or Netzach.",energies:["doctrine and its commentary","teaching","the law and the letter","translation between scales"],tensions:["the general claim against the particular case","breadth against precision","the summary that loses the detail"],attributions:[{lineage:"Ptolemaic",claim:"Mercury is common, beneficent with the beneficent and maleficent with the maleficent, so its character here is read from Jupiter."},{lineage:"Medieval",claim:"Assigned jointly to the learned professions, the law and the schools."},{lineage:"Golden Dawn",claim:"Chesed and Hod, standing on opposite pillars with no direct path between them."}],correspondences:["metals: tin and quicksilver","days: Thursday and Wednesday","sephiroth: Chesed and Hod","Chaldean order: second and sixth of seven"],contested:["The whole beneficent and maleficent sorting is standard in Hellenistic and medieval practice and largely abandoned in modern practice, which reads planetary function without a moral grade. Both readings remain in print and in use.","Whether Mercury takes its colour from a planet by aspect only, or also by sign and by house, is not settled across the sources."],prompts:["Does the wider frame or the exact wording carry more weight in the question being asked?","Which of the two holds dignity by sign here, and does that decide the tone of the other?"]},"Jupiter|Moon":{plain:"Jupiter and the Moon are the planet of increase and the light of the night. One widens; the other holds and reflects.",reading:"The tradition reads this as nourishment at scale: the household made large, the store that does not run out. Hellenistic sources treat the Moon as the body that carries a matter to its outcome, so a benefic joined to it is read as the outcome being carried well. Texts on nativities look to the Moon and the benefics together when asking about the body and its keeping.",principle:"Ptolemy's Tetrabiblos lists Jupiter and Venus as beneficent, Saturn and Mars as maleficent and Mercury as common; most readings of that passage put the Moon on the beneficent side as well, which makes this a meeting of two bodies the older scheme counted favourable. Sect divides them, though: Jupiter belongs to the diurnal sect and the Moon leads the nocturnal one, so their agreement depends on whether the chart is of the day or the night. The Moon is also the swiftest of the seven, and in horary practice it is the body that most often carries light between the others.",energies:["provision","the large household","public feeling","matters carried to their end"],tensions:["appetite without a container","a store that keeps growing and is never enough","day nature meeting night nature"],attributions:[{lineage:"Ptolemaic",claim:"Jupiter is beneficent, and the Moon is counted beneficent in most readings of the same passage."},{lineage:"Hellenistic",claim:"Sect divides them: Jupiter of the day, the Moon of the night."},{lineage:"Horary",claim:"The Moon, being swiftest, is the body most often read as translating light from one planet to another."}],correspondences:["metals: tin and silver","days: Thursday and Monday","sephiroth: Chesed and Yesod, with no path drawn between them","periods: about twelve years and about a month"],contested:["Whether the Moon belongs among the benefics at all is read differently across translations of Ptolemy and across the later schools.","Modern practice has largely dropped the benefic and malefic grading entirely, which removes the ground this reading stands on."],prompts:["Is the chart diurnal or nocturnal, and does that change which of these two is favoured?","What is being enlarged here, and what holds it?"]},"Jupiter|Saturn":{plain:"Jupiter and Saturn are the slowest of the seven classical planets. Their conjunction returns roughly every twenty years.",reading:"Because that is the longest cycle the visible planets make with each other, medieval and Renaissance astrologers built their history-writing on it. The doctrine of great conjunctions, developed at length in the Arabic tradition and taken up in Latin Europe, tracked the meeting as it moved between the triplicities and read a change of age at each shift. The pairing names the frame in which a period is set rather than an event inside it.",principle:"The two are the outer limit of the classical grading: Ptolemy's Tetrabiblos makes Jupiter the greater benefic and Saturn the greater malefic, adjacent in the Chaldean order and yet at the extremes of what that order was taken to mean. Both belong to the diurnal sect, which in Hellenistic practice is the one condition held to soften Saturn. On the Golden Dawn Tree they fall at Binah and Chesed, on either side of the Abyss, so the system that draws paths almost everywhere else declines to draw one here.",energies:["structure and its enlargement","the long cycle","law","the frame of an age"],tensions:["increase against limit","the boundary that grows and the growth that hardens","time measured against time spent"],attributions:[{lineage:"Ptolemaic",claim:"Jupiter the greater benefic and Saturn the greater malefic: the extremes of the classical grading."},{lineage:"Medieval Arabic",claim:"The doctrine of great conjunctions reads the roughly twenty-year Jupiter-Saturn meeting, and its shift between triplicities, as the marker of historical periods."},{lineage:"Hellenistic",claim:"Both are of the diurnal sect, and a day chart is held to moderate Saturn."},{lineage:"Golden Dawn",claim:"Binah and Chesed, separated by the Abyss, with no path drawn between them."}],correspondences:["metals: tin and lead","days: Thursday and Saturday","sephiroth: Binah and Chesed","conjunction cycle: about twenty years"],contested:["The benefic and malefic grading behind this pairing is Hellenistic doctrine kept through the medieval period and largely abandoned by modern practice, which reads Saturn as structure rather than harm. Traditional revivalists have restored the older reading; the two are not compatible.","How much the great-conjunction doctrine claims, a change of dynasty or only a change of tone, varies widely between the sources that hold it."],prompts:["Where does the most recent conjunction of these two fall in this chart, and in which triplicity?","Is the working concerned with the limit or with what presses against it?"]},"Jupiter|Sun":{plain:"Jupiter and the Sun are the planet of increase and the light of the day. One is the source; the other widens what the source gives.",reading:"The tradition reads the two together as sovereignty and its patronage: the ruler and the counsellor, the throne and the endowment. Hellenistic sources read them technically as well, since Jupiter shares the sect of the Sun and its position relative to the Sun, rising before it or setting after it, was held to change how it acts. Renaissance texts on magic pair solar and Jovian material where the aim is dignity or favour.",principle:"Both belong to the diurnal sect, which in the older system is the strongest thing two planets can hold in common. Ptolemy's Tetrabiblos lists Jupiter among the beneficent planets alongside Venus, sets Saturn and Mars against them as maleficent and calls Mercury common, while treating the Sun by its heat and dryness rather than grading it on that scale at all. On the Golden Dawn Tree the two fall at Chesed and Tiphareth, joined by the path of Yod, which carries the Hermit, so the system routes the meeting of the throne and its benefactor through the figure who withdraws from both.",energies:["patronage","dignity","endowment","the confident centre"],tensions:["the light overshadowing what stands near it","generosity spending the source","office confused with the one holding it"],attributions:[{lineage:"Hellenistic",claim:"Jupiter and the Sun are both diurnal, and a day chart is held to strengthen both together."},{lineage:"Ptolemaic",claim:"Jupiter is beneficent; the Sun is described by heat and dryness rather than by benefit and harm."},{lineage:"Medieval",claim:"A planet close to the Sun is read as combust and its own significations obscured; at very close orb the same texts call it cazimi and read the reverse."},{lineage:"Golden Dawn",claim:"Chesed and Tiphareth, joined by the path of Yod, the Hermit."}],correspondences:["metals: tin and gold","days: Thursday and Sunday","sephiroth: Chesed and Tiphareth"],contested:["Where combustion begins and where cazimi takes over differ between sources, and whether either applies to a benefic in the same way is not agreed.","The benefic grading itself is Hellenistic and medieval doctrine, largely set aside in modern practice."],prompts:["What is the separation in degrees, and does it fall inside the range the sources call combust?","Is the matter here the source, or the thing built on the source?"]},"Jupiter|Venus":{plain:"Jupiter and Venus are the two planets the older astrology called benefic. One enlarges; the other draws together and pleases.",reading:"Read as a pair they are the classical signature of ease: ornament, the feast, patronage of the arts, the settled house. Medieval texts assign them jointly to pleasure taken without apparent cost, and warn in the same breath that the cost is only deferred. The Renaissance image tradition puts them together wherever abundance is being shown rather than earned.",principle:"This is the pairing the benefic category was written around. Ptolemy's Tetrabiblos names Jupiter and Venus as the beneficent planets, Saturn and Mars as maleficent and Mercury as common. Sect still divides them, Jupiter belonging to the day and Venus to the night, so the older practice reads one of them as better placed in any given chart rather than reading both as simply good. On the Golden Dawn Tree they fall at Chesed and Netzach, joined by the path of Kaph, the Wheel of Fortune, which is itself attributed to Jupiter: Jupiter reaching Venus along its own road.",energies:["ornament","abundance","hospitality","ease of manner"],tensions:["surplus without discipline","taste enlarged into excess","the pleasant reading that avoids the hard one"],attributions:[{lineage:"Ptolemaic",claim:"The two beneficent planets of the classical scheme, greater and lesser."},{lineage:"Hellenistic",claim:"Sect divides them: Jupiter diurnal, Venus nocturnal."},{lineage:"Golden Dawn",claim:"Chesed and Netzach, both on the Pillar of Mercy, joined by the path of Kaph, the Wheel of Fortune, a Jovian path."}],correspondences:["metals: tin and copper","days: Thursday and Friday","sephiroth: Chesed and Netzach","both on the Pillar of Mercy"],contested:["Modern practice has largely abandoned the benefic and malefic grading, and with it the idea that this pairing is simply favourable. Traditional revivalists keep it. Reading either way changes what the pairing is taken to mean, and the sources do not settle it.","Whether an unmixed benefic pairing was ever read as wholly good, or always with the medieval caution about softness attached, depends on which text is followed."],prompts:["Does anything else in the chart supply the restraint that neither of these two carries?","Which of the two is the better placed by sect here?"]},"Mars|Mercury":{plain:"Mars and Mercury are the planet of the cut and the planet of the word. Together they name the sharpened statement.",reading:"The tradition gives this pairing to the argument, the debate and the blade of speech, and also to the hand that works with tools. Medieval sources list it under crafts that require accuracy and force at once, the surgeon and the engraver among them, and under contention conducted in words. What one supplies as precision the other supplies as pressure.",principle:"Ptolemy's Tetrabiblos counts Mars among the maleficent planets alongside Saturn, sets Jupiter and Venus against them as beneficent, and calls Mercury common, taking its character from whatever it is joined to, so the classical reading treats Mercury here as sharpened rather than as neutral. On the Golden Dawn Tree the two fall at Geburah and Hod, both on the Pillar of Severity, joined by the path of Mem, which carries the Hanged Man and the element of water: the severe pillar crossed by the card of suspension.",energies:["argument","precision under pressure","the craft that cuts","quick decision"],tensions:["speech that wounds","haste taken for clarity","the sharp answer that closes the question"],attributions:[{lineage:"Ptolemaic",claim:"Mars is maleficent and Mercury common, so the common planet takes the malefic tone."},{lineage:"Medieval",claim:"Assigned to crafts requiring both accuracy and force, and to contention conducted in speech."},{lineage:"Golden Dawn",claim:"Geburah and Hod, both on the Pillar of Severity, joined by the path of Mem, the Hanged Man."}],correspondences:["metals: iron and quicksilver","days: Tuesday and Wednesday","sephiroth: Geburah and Hod","both on the Pillar of Severity"],contested:["The malefic classification of Mars, and with it the reading of Mercury as damaged by contact with it, is standard in Hellenistic and medieval practice and largely dropped by modern astrology, which reads the pairing as directness rather than harm.","Whether the pairing signifies the tongue or the hand is divided between the sources; the medieval lists give both without choosing."],prompts:["Is the sharpness here in the tool or in the use of the tool?","Which house holds this pairing, and what matter does that house govern?"]},"Mars|Moon":{plain:"Mars and the Moon are the planet of the cut and the light of the night. One provokes; the other registers.",reading:"The tradition reads this pairing as feeling that moves quickly into action, and as the body reacting before the reason does. Medieval texts on nativities associate it with fever, with sudden appetite and with swift change of mood, the Moon governing the humours and Mars the heat. Both belong to the nocturnal sect, so the older practice does not treat them as strangers.",principle:"Sect is the structural fact here. Ptolemy's Tetrabiblos grades Mars and Saturn as maleficent against Jupiter and Venus as beneficent, with Mercury common, and Hellenistic practice holds that a malefic of the nocturnal sect does less damage in a night chart. The Moon leads that sect, so a nocturnal chart is the condition under which the older sources read this pairing most mildly. The Moon is also the swiftest of the seven, so in horary work it is the usual carrier of light, and a malefic it carries to is read as receiving what the Moon brings.",energies:["reflex","heat","protective force","appetite that arrives whole"],tensions:["reaction outrunning judgement","the mood that becomes an act","safety sought through force"],attributions:[{lineage:"Ptolemaic",claim:"Mars is maleficent, and the Moon is counted beneficent in most readings of the same passage."},{lineage:"Hellenistic",claim:"Both are of the nocturnal sect, and a night chart is held to reduce the harm attributed to Mars."},{lineage:"Horary",claim:"The Moon, being swiftest, is the body most often read as translating light from one planet to another."}],correspondences:["metals: iron and silver","days: Tuesday and Monday","sephiroth: Geburah and Yesod, with no path drawn between them","both of the nocturnal sect"],contested:["Modern practice has largely abandoned the malefic grading, reading Mars as drive rather than harm; traditional revivalists keep it. The pairing reads very differently under the two schemes.","Whether sect materially changes a reading, or is a refinement safely ignored, divides traditional from mainstream modern practice."],prompts:["Is this chart diurnal or nocturnal, and does the older sect rule alter what is read here?","What is being defended, and what is doing the defending?"]},"Mars|Saturn":{plain:"Mars and Saturn are the two planets the older astrology called malefic. One strikes; the other withholds.",reading:"Medieval and Renaissance texts treat their meeting as the hardest combination in the classical set, and mundane astrology watched their conjunctions closely when writing about conflict. The reading is not doubled violence but two opposite failures held together: force applied where there is no give, and delay where force is already in motion. What is named is a bind, not an outcome.",principle:"The classical grading in Ptolemy's Tetrabiblos makes Saturn the greater malefic and Mars the lesser, against Jupiter and Venus as the benefics, with Mercury common between them, so this is the pairing the maleficent category was built to describe. Sect separates them: Saturn is of the diurnal sect and Mars of the nocturnal, so one of the two is always the better placed and the other the worse, a night chart easing Mars and worsening Saturn and a day chart the reverse. On the Golden Dawn Tree they fall at Binah and Geburah on the Pillar of Severity, joined by the path of Cheth, which carries the Chariot.",energies:["endurance under pressure","hard labour","the disciplined blow","obstruction met head on"],tensions:["force against inertia","cruelty and its rationalisation","the effort that costs more than the object"],attributions:[{lineage:"Ptolemaic",claim:"Saturn the greater malefic and Mars the lesser: the two maleficent planets of the classical scheme."},{lineage:"Hellenistic",claim:"Sect divides them, Saturn diurnal and Mars nocturnal, so a chart favours one and not the other."},{lineage:"Medieval mundane",claim:"Conjunctions of the two were watched closely in writing about conflict, famine and hardship."},{lineage:"Golden Dawn",claim:"Binah and Geburah, both on the Pillar of Severity, joined by the path of Cheth, the Chariot."}],correspondences:["metals: iron and lead","days: Tuesday and Saturday","sephiroth: Binah and Geburah","both on the Pillar of Severity"],contested:["The malefic category is Hellenistic and medieval doctrine. Most modern practice has abandoned it, reading Saturn as structure and Mars as drive with no moral grade attached; traditional revivalists have restored it in full. No single reading satisfies both.","Whether the two malefics together are worse than either alone, or whether they check each other, is answered both ways in the medieval sources."],prompts:["Which of the two is in sect in this chart, and does that rule change the weight given to each?","Is the obstruction here external, or is it the shape of the effort itself?"]},"Mars|Sun":{plain:"Mars and the Sun are the planet of the cut and the light of the day. One is the source of light; the other is the edge that acts within it.",reading:"The tradition reads the pairing as will made visible: the ruler who takes the field, the assertion carrying the authority of the centre. Older texts read it technically as well, since Mars near the Sun is called combust and its own significations read as burnt away, so the closer the contact the more the reading concerns the Sun and not Mars. What is named is the difference between acting from the centre and being swallowed by it.",principle:"Ptolemy's Tetrabiblos grades Mars and Saturn as maleficent and Jupiter and Venus as beneficent, calls Mercury common, and treats the Sun by heat and dryness rather than placing it on that scale, so the classical sorting reaches only half of this pair. Sect divides them: the Sun leads the diurnal sect and Mars belongs to the nocturnal one, which makes Mars out of sect in a day chart and eased in a night chart. On the Golden Dawn Tree they fall at Tiphareth and Geburah, joined by the path of Lamed, which carries Justice, so force reaches the centre by way of the scales.",energies:["assertion","courage in the open","authority exercised directly","heat"],tensions:["the will that will not be checked","the edge burnt away by the source","office taken for a weapon"],attributions:[{lineage:"Ptolemaic",claim:"Mars is maleficent; the Sun is graded by heat and dryness rather than by benefit and harm."},{lineage:"Hellenistic",claim:"Mars is out of sect in a day chart and in sect at night; the Sun is the reverse."},{lineage:"Medieval",claim:"A planet close to the Sun is read as combust and its significations obscured; at very close orb the same texts call it cazimi and read the reverse."},{lineage:"Golden Dawn",claim:"Tiphareth and Geburah, joined by the path of Lamed, Justice."}],correspondences:["metals: iron and gold","days: Tuesday and Sunday","sephiroth: Tiphareth and Geburah"],contested:["The combust and cazimi boundaries differ between sources, and modern practice mostly disregards both.","The malefic grading of Mars is classical doctrine largely abandoned in modern astrology, which reads it as drive without a moral grade."],prompts:["What is the exact separation in degrees, and where does it fall against the combust range the sources give?","Is the action here coming from the centre, or standing in front of it?"]},"Mars|Venus":{plain:"Mars and Venus are the planet of the cut and the planet of attraction. One goes toward; the other draws in.",reading:"Outside the two lights this is the oldest named pair in the Western repertoire. The Roman poem De Rerum Natura opens by placing Mars in the lap of Venus, and Renaissance painting returned to that image as the disarming of force by beauty. Astrologically the pairing is read as desire and its pursuit held as two motions rather than one: what is wanted, and what is done about wanting it.",principle:"In Ptolemy's grading Venus is the lesser benefic and Mars the lesser malefic, an exact opposition of category at equal rank, with Jupiter and Saturn as the greater pair above them and Mercury common between. Unusually, the two share a sect, both belonging to the night, so the older system reads them as agreeing on when they act and disagreeing on how. On the Golden Dawn Tree they fall at Geburah on the Pillar of Severity and Netzach on the Pillar of Mercy, with no path drawn directly between them.",energies:["desire","pursuit","the charged encounter","attraction with an edge"],tensions:["wanting against taking","the pursuit that destroys the object","force mistaken for ardour"],attributions:[{lineage:"Ptolemaic",claim:"Venus the lesser benefic and Mars the lesser malefic: opposed in kind, equal in rank."},{lineage:"Hellenistic",claim:"Both are of the nocturnal sect."},{lineage:"Renaissance",claim:"The image of Venus disarming Mars is a repeated subject in painting and in the poetry the painters drew on."},{lineage:"Golden Dawn",claim:"Geburah and Netzach, on opposing pillars, with no direct path between them."}],correspondences:["metals: iron and copper","days: Tuesday and Friday","sephiroth: Geburah and Netzach","both of the nocturnal sect"],contested:["Treating this pairing as a verdict about attraction between two people is a later habit; the older texts read it as two significators standing in a relation and left the application to the astrologer.","The benefic and malefic labels that define the contrast here are classical doctrine largely abandoned by modern practice, which reads the pair as two appetites rather than as a good and a harm."],prompts:["Which of the two holds the stronger dignity here, and does that decide which motion leads?","Is the matter under question the wanting or the acting?"]},"Mercury|Moon":{plain:"Mercury and the Moon are the two swiftest of the seven classical bodies. One names; the other holds.",reading:"The tradition pairs them as mind and memory, the word and the store it draws from. Medieval texts read the Moon as what has been taken in and Mercury as what can be said back, and treat the combination as the signature of ready recall and of speech that follows feeling closely. Both change quickly, so the older sources warn that a reading taken from this pair alone is a reading of a moment.",principle:"The Moon crosses the zodiac in about a month, and Mercury, tethered to the Sun, in about a year, with a daily motion that varies more than any other classical body; they are the two the older astrology treats as least fixed. Ptolemy's Tetrabiblos calls Mercury common, beneficent with the beneficent and maleficent with the maleficent, and most readings of the same passage place the Moon among the beneficent, so this pairing has no settled grade of its own within the classical scheme. On the Golden Dawn Tree they fall at Hod and Yesod, joined by the path of Resh, which is given the card of the Sun: two night-side sephiroth connected by a solar road.",energies:["recall","quick uptake","speech close to feeling","the reported impression"],tensions:["talking as a way of not feeling","the impression taken for the fact","restlessness in both directions"],attributions:[{lineage:"Ptolemaic",claim:"Mercury is common and takes its character from what it touches; the Moon is counted beneficent in most readings."},{lineage:"Hellenistic",claim:"Mercury has no sect of its own and is assigned to the day or the night sect according to whether it rises before or sets after the Sun."},{lineage:"Horary",claim:"The Moon, being swiftest, is the body most often read as translating light between planets, with Mercury next in speed."},{lineage:"Golden Dawn",claim:"Hod and Yesod, joined by the path of Resh, the Sun."}],correspondences:["metals: quicksilver and silver","days: Wednesday and Monday","sephiroth: Hod and Yesod","periods: about a month and about a year"],contested:["Whether the Moon belongs among the benefics is read differently across translations of Ptolemy, and modern practice has largely set the benefic and malefic grading aside altogether.","Mercury's sect assignment depends on its position relative to the Sun, and the sources differ on where that boundary falls."],prompts:["Which is faster in this chart by daily motion, and does that decide which leads?","Is what is being named here a memory or an observation?"]},"Mercury|Saturn":{plain:"Mercury and Saturn are the planet of the word and the planet of the limit. One articulates; the other holds a form until it sets.",reading:"The tradition reads this pairing as the disciplined mind: the register, the measurement, the argument built to carry weight. Medieval texts assign it to the professions that keep records and to study that continues past interest. What is named is not slowness but the refusal to release a formulation before it is exact.",principle:"Ptolemy's Tetrabiblos counts Saturn as the greater malefic and Mars as the lesser, sets Jupiter and Venus against them as the benefics, and calls Mercury common, taking the tone of whatever it joins, so the classical reading treats Mercury here as weighted rather than neutral. Both stand on the Golden Dawn Pillar of Severity, at Binah and Hod, and yet no path is drawn between them: within that system the two ends of the severe pillar do not touch directly. In the Chaldean order they sit at first and sixth of seven, which is why the medieval texts on planetary hours place their hours furthest apart.",energies:["method","the record","sustained study","exact formulation"],tensions:["thought that will not close","doubt taken for rigour","the form outlasting what it was made for"],attributions:[{lineage:"Ptolemaic",claim:"Saturn is the greater malefic and Mercury common, so the common planet takes the malefic tone."},{lineage:"Medieval",claim:"Assigned to record-keeping, measurement and long study."},{lineage:"Golden Dawn",claim:"Binah and Hod, the two ends of the Pillar of Severity, with no direct path drawn between them."}],correspondences:["metals: quicksilver and lead","days: Wednesday and Saturday","sephiroth: Binah and Hod","Chaldean order: first and sixth of seven"],contested:["The reading of Mercury as damaged by Saturn follows from the malefic grading, which most modern practice has abandoned in favour of reading Saturn as structure without harm. Traditional revivalists retain the older reading.","Whether Mercury takes on the character of a planet by aspect only, or also by sign and by house, is not settled across the sources."],prompts:["Is the exactness here serving the question or postponing it?","Which of the two holds dignity in this chart, and what does that do to the other?"]},"Mercury|Sun":{plain:"Mercury never appears more than about twenty-eight degrees from the Sun as seen from the earth, so the two are never far apart in any chart.",reading:"Because of that limit the conjunction is the only major aspect the pair can form, and the tradition reads them through nearness rather than through angle. Medieval texts call a planet close to the Sun combust and read its own significations as obscured; at very close orb they call it cazimi, in the heart of the Sun, and read it as strengthened instead. The pairing is the word standing beside the light it reports on.",principle:"The astronomical constraint is the structure: Mercury is an inferior planet, so its elongation has a hard maximum, and every doctrine about the pair is built on that fact. The classical grading, which in Ptolemy's Tetrabiblos makes Jupiter and Venus beneficent, Saturn and Mars maleficent and Mercury common, has little purchase here, since Mercury takes its character from what it touches and the Sun is described by heat rather than sorted as benefit or harm. On the Golden Dawn Tree the two fall at Tiphareth and Hod, joined by the path of Ayin, which carries the Devil.",energies:["the report","articulation of what is central","counsel","naming the light"],tensions:["the messenger mistaken for the message","speech burnt out by proximity","commentary standing in for the thing"],attributions:[{lineage:"Astronomical",claim:"Mercury reaches a maximum elongation from the Sun of roughly twenty-eight degrees, so conjunction is the only major aspect available."},{lineage:"Medieval",claim:"Combustion obscures a planet near the Sun; cazimi, at very close orb, is read as the opposite."},{lineage:"Ptolemaic",claim:"Mercury is common and takes the character of whatever it is joined to."},{lineage:"Golden Dawn",claim:"Tiphareth and Hod, joined by the path of Ayin, the Devil."}],correspondences:["metals: quicksilver and gold","days: Wednesday and Sunday","sephiroth: Tiphareth and Hod","maximum elongation: about twenty-eight degrees"],contested:["The orb at which combustion begins and the orb at which cazimi takes over differ between sources, and modern practice mostly disregards both.","Whether Mercury rising before the Sun and Mercury setting after it should be read as materially different conditions is standard in traditional practice and uncommon in modern practice."],prompts:["What is the exact separation in degrees, and which of the conditions do the sources place it in?","Does Mercury rise before the light here, or set after it?"]},"Mercury|Venus":{plain:"Mercury and Venus are the two inferior planets, both bound to the Sun. Neither can be far from it, and so they are never far from each other; their maximum separation is about seventy-five degrees.",reading:"The tradition pairs them as the word and what makes the word pleasing: rhetoric, ornament, craft applied to language, the arts that need a form and a technique together. Medieval sources list them under the trades requiring skill of the hand and judgement of the eye. Because their separation is capped, the aspects available are few, and the older texts read them more often as companions than as antagonists.",principle:"Both orbit inside the earth, which is the astronomical fact that limits their elongation and therefore their possible aspects: the sextile is the widest major angle they can make, and square, trine and opposition are impossible. In Ptolemy's grading Venus is the lesser benefic, Jupiter the greater, Saturn and Mars the malefics, and Mercury common, so the classical reading gives Mercury the benefic tone here. On the Golden Dawn Tree they fall at Hod and Netzach, one on each of the outer pillars, joined by the path of Peh, which carries the Tower and is itself attributed to Mars.",energies:["rhetoric","craft","ornamented speech","sociability"],tensions:["charm standing in for accuracy","the well-made argument that is not true","manner over matter"],attributions:[{lineage:"Astronomical",claim:"Both are inferior planets; their maximum mutual separation is roughly seventy-five degrees, so square, trine and opposition cannot occur between them."},{lineage:"Ptolemaic",claim:"Venus is the lesser benefic and Mercury is common, so Mercury takes the benefic tone."},{lineage:"Golden Dawn",claim:"Hod and Netzach, joined by the path of Peh, the Tower, a Martial path."}],correspondences:["metals: quicksilver and copper","days: Wednesday and Friday","sephiroth: Hod and Netzach","both inferior planets"],contested:["The benefic classification behind the pleasant reading of this pair is Hellenistic doctrine that modern practice has largely set aside.","Commentators differ on how to read a Martial path joining the two most sociable sephiroth; the attribution is standard, its sense is not agreed."],prompts:["What is the actual separation, and which of the few available aspects does it make?","Is the craft here serving the content or replacing it?"]},"Moon|Saturn":{plain:"The Moon and Saturn are the swiftest and the slowest of the seven classical planets. One changes constantly; the other barely moves.",reading:"The tradition reads the pairing as feeling under constraint: the container and what it contains, the memory that does not fade, the mood hardened into a habit of mind. Medieval texts assign the combination to fasting, to solitude and to prolonged sorrow, and treat it as the clearest case of a malefic acting on a light. It is one of the pairings the older sources describe most darkly and the modern ones most gently.",principle:"This is the widest gap in the classical set: the Moon crosses the zodiac in about a month and Saturn takes roughly twenty-nine and a half years. Ptolemy's Tetrabiblos makes Saturn the greater malefic, sets Jupiter and Venus against it as the benefics, calls Mercury common, and on most readings counts the Moon beneficent, which makes this contact the textbook instance of a malefic afflicting a light. Sect divides them cleanly, Saturn being diurnal and the Moon leading the nocturnal sect, so neither is placed to soften the other. On the Golden Dawn Tree they fall at Binah, titled the Great Sea, and Yesod, titled the Foundation, with no path drawn between them.",energies:["containment","endurance","long memory","solitude"],tensions:["feeling held in a shape too narrow for it","the past kept rather than digested","care that becomes duty"],attributions:[{lineage:"Ptolemaic",claim:"Saturn is the greater malefic, and the Moon is counted beneficent in most readings of the same passage."},{lineage:"Hellenistic",claim:"Opposite sects, Saturn diurnal and the Moon nocturnal, so neither eases the other."},{lineage:"Medieval",claim:"Assigned to fasting, solitude and prolonged sorrow."},{lineage:"Golden Dawn",claim:"Binah and Yesod, with no path drawn between them."}],correspondences:["metals: silver and lead","days: Monday and Saturday","sephiroth: Binah and Yesod","periods: about a month and about twenty-nine and a half years"],contested:["The older texts read this pairing as one of the hardest in the set; most modern astrology reads it as maturity, containment or slow-forming competence. The difference is not one of emphasis but of what the tradition is taken to be for.","Whether the Moon should be graded beneficent at all is read differently across translations of Ptolemy."],prompts:["What is the aspect and the orb, before anything is said about what it means?","What is the shape of the container, and what was it built to hold?"]},"Moon|Sun":{plain:"The Sun and the Moon are the two lights. Their angular separation is the phase of the Moon, and it is the one relation in a chart that can be seen with the eye.",reading:"The visible calendar is built on this pair: new at the conjunction, full at the opposition, the quarters at the squares. Hellenistic astrology reads the two as the sects themselves, day and night, and computes the Lot of Fortune from the arc between them projected from the ascendant. Alchemical texts name them Sol and Luna and make their joining, the coniunctio, the central image of the work.",principle:"Sect is founded on this pair: the Sun leads the diurnal sect with Jupiter and Saturn, the Moon leads the nocturnal with Venus and Mars, and Mercury joins whichever it is nearer to by rising. Neither light is graded on the scale that sorts the other five, since Ptolemy's Tetrabiblos names Jupiter and Venus beneficent, Saturn and Mars maleficent and Mercury common while treating the lights as the sources against which the rest are measured. On the Golden Dawn Tree they fall at Tiphareth and Yesod, adjacent on the Middle Pillar, joined by the path of Samekh, which carries Temperance: the card of mixing set between the two things being mixed.",energies:["the phase","day and night","the visible cycle","the joining of two lights"],tensions:["the light that outshines and the light that reflects","waxing against waning","the conjunction at which one light is not seen at all"],attributions:[{lineage:"Hellenistic",claim:"The pair defines sect: the Sun leads the day sect, the Moon the night sect."},{lineage:"Hellenistic",claim:"The Lot of Fortune is computed from the arc between the two projected from the ascendant, with the direction reversed in a night chart."},{lineage:"Alchemical",claim:"Sol and Luna, whose coniunctio is the recurring image of the work in the illustrated treatises."},{lineage:"Golden Dawn",claim:"Tiphareth and Yesod, adjacent on the Middle Pillar, joined by the path of Samekh, Temperance."}],correspondences:["metals: gold and silver","days: Sunday and Monday","sephiroth: Tiphareth and Yesod","phase cycle: about twenty-nine and a half days from new to new"],contested:["Whether the Lot of Fortune should be reversed by sect is settled in the Hellenistic sources and contested in later practice, where some schools compute it the same way by day and by night.","Modern practice often reads the two lights as parts of a single self; the older practice reads them as separate significators with separate jurisdictions. The two approaches ask different questions of the same distance."],prompts:["What was the phase at this moment, and where does the prenatal syzygy fall?","Which of the two lights stands above the horizon here?"]},"Moon|Venus":{plain:"The Moon and Venus are the light of the night and the planet of attraction. One receives; the other draws.",reading:"The tradition reads this as the softest pairing among the seven: the settled house, the pleasure that also comforts, ornament serving care rather than display. Medieval texts assign it to hospitality, to arts practised at home, and to the giving of things that were made rather than bought. Both belong to the nocturnal sect, so the older practice reads them as working under the same conditions.",principle:"Ptolemy's Tetrabiblos names Venus the lesser benefic and Jupiter the greater, sets Saturn and Mars against them as maleficent and calls Mercury common; most readings of the same passage count the Moon among the beneficent as well, which makes this one of the few pairings the classical grading treats as unmixed. Sect agrees with the grading here, both being nocturnal and the Moon leading that sect, so a night chart strengthens both at once, a rare alignment in a system built mostly on division. On the Golden Dawn Tree they fall at Netzach and Yesod, joined by the path of Tzaddi.",energies:["comfort","hospitality","made things given away","receptive pleasure"],tensions:["ease that will not be disturbed","care that avoids the difficult conversation","softness with no edge to hold it"],attributions:[{lineage:"Ptolemaic",claim:"Venus is the lesser benefic, and the Moon is counted beneficent in most readings of the same passage."},{lineage:"Hellenistic",claim:"Both are of the nocturnal sect and so both are strengthened by a night chart."},{lineage:"Golden Dawn",claim:"Netzach and Yesod, joined by the path of Tzaddi, which carries the Star in the standard arrangement."}],correspondences:["metals: silver and copper","days: Monday and Friday","sephiroth: Netzach and Yesod","both of the nocturnal sect"],contested:["The Star sits on the path of Tzaddi in the Golden Dawn arrangement, but Crowley exchanged the Star and the Emperor between their letters on the strength of a line in the Book of the Law, which changes which card stands on this path. Both arrangements remain in use, and a working has to choose one.","The benefic grading that makes this pairing read as gentle is classical doctrine largely abandoned in modern practice."],prompts:["Which arrangement of the paths does this working follow?","Is the comfort here a resource, or a place to stop?"]},"Saturn|Sun":{plain:"Saturn and the Sun are the slowest of the classical planets and the source of the light. One sets a limit; the other is what the limit is set upon.",reading:"The tradition reads the pairing as authority under constraint: the office with its duties attached, the sovereign answerable to law, the light passing through a narrow opening. Medieval texts read Saturn near the Sun as combust and treat the contact as costing Saturn its own voice, while the nativity literature reads the same contact as the mark of responsibility arriving early or arriving heavily.",principle:"Sect is the structural fact. Ptolemy's Tetrabiblos makes Saturn the greater malefic against Jupiter and Venus as the benefics, with Mercury common, but Saturn is of the day sect, and Hellenistic practice holds that a malefic in its own sect does less harm. Since the Sun leads that sect, this is the pairing in which Saturn is at its least destructive by the older rules, which is why traditional and modern readings converge here more than they do elsewhere. On the Golden Dawn Tree the two fall at Binah and Tiphareth, joined by the path of Zayin, which carries the Lovers: the card of choice set between the limit and the light.",energies:["office","responsibility","structure given a centre","the long form of an ambition"],tensions:["the light narrowed by its duties","authority that outlives its warrant","cost counted before the thing is attempted"],attributions:[{lineage:"Ptolemaic",claim:"Saturn is the greater malefic; the Sun is graded by heat and dryness rather than by benefit and harm."},{lineage:"Hellenistic",claim:"Both are of the diurnal sect, and a malefic in sect is held to act with less damage."},{lineage:"Medieval",claim:"Saturn near the Sun is read as combust, its own significations obscured."},{lineage:"Golden Dawn",claim:"Binah and Tiphareth, joined by the path of Zayin, the Lovers."}],correspondences:["metals: gold and lead","days: Sunday and Saturday","sephiroth: Binah and Tiphareth","Chaldean order: first and fourth of seven"],contested:["The malefic grading of Saturn is Hellenistic and medieval doctrine largely abandoned by modern practice, which reads Saturn as structure and maturity rather than harm. Traditional revivalists have restored the older reading in full.","Whether combustion damages a slow planet as much as a fast one is answered differently by the medieval sources."],prompts:["Is this chart diurnal, and does the sect rule change the weight given to Saturn here?","What is the limit made of, and who set it?"]},"Saturn|Venus":{plain:"Saturn and Venus are the planet of the limit and the planet of attraction. One withholds; the other draws in.",reading:"The tradition reads this as attachment tested against time: the long commitment, the austere beauty, the pleasure rationed or deferred. Medieval texts assign it to unions contracted on grounds other than desire, to arts practised under constraint, and to a taste preferring the plain to the ornate. What is named is the meeting of a thing that wants closeness with a thing that keeps distance.",principle:"In Ptolemy's grading Venus is the lesser benefic and Saturn the greater malefic, and unlike Jupiter against Mars these two are not matched in rank, the malefic being the heavier of the pair, which is why the medieval texts read Saturn as setting the terms. Mercury stands common between the two categories, and Jupiter balances Saturn at the other end. Sect divides these two as well, Saturn being diurnal and Venus nocturnal, so neither is placed to ease the other. On the Golden Dawn Tree they fall at Binah on the Pillar of Severity and Netzach on the Pillar of Mercy, with no path drawn between them.",energies:["durable attachment","austerity of form","the long commitment","restraint as a style"],tensions:["warmth held at arm's length","value measured only by what it cost","the pleasure postponed until it is no longer wanted"],attributions:[{lineage:"Ptolemaic",claim:"Venus the lesser benefic and Saturn the greater malefic: unequal in rank as well as opposed in kind."},{lineage:"Hellenistic",claim:"Opposite sects, Saturn diurnal and Venus nocturnal."},{lineage:"Medieval",claim:"Assigned to commitments made on grounds other than desire, and to art made under constraint."},{lineage:"Golden Dawn",claim:"Binah and Netzach, on opposing pillars, with no direct path between them."}],correspondences:["metals: copper and lead","days: Friday and Saturday","sephiroth: Binah and Netzach"],contested:["The reading of Venus as harmed by Saturn depends entirely on the malefic grading, which most modern practice has dropped in favour of reading Saturn as commitment and duration. Under that reading the same contact is favourable rather than difficult, and the sources give no way to decide between them.","Whether the greater malefic outweighs the lesser benefic, or the two cancel, is answered both ways in the medieval literature."],prompts:["What is being kept here, and what is the keeping costing?","Which of the two holds the stronger dignity by sign in this chart?"]},"Sun|Venus":{plain:"Venus never appears more than about forty-seven degrees from the Sun as seen from the earth, so the two are always close in a chart and the aspects between them are few.",reading:"The tradition reads the pairing as the light and what adorns it: favour, taste, the pleasing face of an authority. Medieval texts read it technically as well, since Venus near the Sun is called combust and its own significations read as obscured, and Venus rising before the Sun is distinguished from Venus setting after it. As the morning and evening star, Venus is the body most often seen beside the light.",principle:"The astronomical constraint governs the doctrine: Venus is an inferior planet, so its elongation is capped near forty-seven degrees, which rules out the square, the trine and the opposition and leaves the conjunction and the smaller angles. In Ptolemy's grading Venus is the lesser benefic and Jupiter the greater, Saturn and Mars are the malefics and Mercury is common, while the Sun is described by heat rather than sorted at all, so the classical scheme reaches only one half of this pair. On the Golden Dawn Tree the two fall at Tiphareth and Netzach, joined by the path of Nun, which carries Death.",energies:["favour","adornment of what is central","grace of manner","the morning and evening star"],tensions:["the ornament obscuring what it decorates","approval sought at the centre","beauty burnt out by nearness"],attributions:[{lineage:"Astronomical",claim:"Venus reaches a maximum elongation of roughly forty-seven degrees, so square, trine and opposition to the Sun cannot occur."},{lineage:"Ptolemaic",claim:"Venus is the lesser benefic; the Sun is graded by heat and dryness rather than by benefit and harm."},{lineage:"Medieval",claim:"Combustion obscures a planet near the Sun; the same texts distinguish Venus rising before the Sun from Venus setting after it."},{lineage:"Golden Dawn",claim:"Tiphareth and Netzach, joined by the path of Nun, Death."}],correspondences:["metals: gold and copper","days: Sunday and Friday","sephiroth: Tiphareth and Netzach","maximum elongation: about forty-seven degrees"],contested:["The orb at which combustion is held to begin varies between sources, and modern practice mostly disregards the doctrine.","Whether the morning star and evening star conditions of Venus should be read as materially different is standard in traditional practice and uncommon in modern practice."],prompts:["What is the separation in degrees, and is Venus rising before the light or setting after it?","Is the matter here the centre, or what has been placed around it?"]}};function l(e,t){if(!e||!t||e===t)return null;const a=[e,t].sort().join("|");return d[a]||null}const i=Object.keys(n),o=[];for(let e=0;e<i.length;e++)for(let t=e+1;t<i.length;t++){const a=i[e],s=i[t],r=l(a,s);r&&(o.push([`${n[a]}+${n[s]}`,h(r)]),o.push([`${n[s]}+${n[a]}`,h(r)]))}const m=Object.fromEntries(o);export{m as P};
